+    if (global_node == 0) return grid->lower[dir];
+    if (global_node == num_nodes*grid->cells[dir]) return grid->upper[dir];
+    cell = (double) global_node/num_nodes;
+  }
+  return grid->lower[dir] + cell*grid->dx[dir];
+}

